import inspect
import re


def kernel_function(description="", name=None):
    def decorate(fn):
        fn.__kernel_function__ = True
        fn.__kernel_name__ = name or fn.__name__
        fn.__kernel_description__ = description
        return fn
    return decorate


class Kernel:
    def __init__(self):
        self.services = {}
        self.plugins = {}
        self.filters = []

    def add_service(self, service_id, service):
        self.services[service_id] = service
        return self

    def add_plugin(self, instance, plugin_name):
        functions = {}
        for attr in dir(instance):
            member = getattr(instance, attr)
            if getattr(member, "__kernel_function__", False):
                functions[member.__kernel_name__] = member
        self.plugins[plugin_name] = functions
        return functions

    def add_filter(self, fn):
        self.filters.append(fn)
        return self

    def catalog(self):
        entries = []
        for plugin_name in sorted(self.plugins):
            for function_name in sorted(self.plugins[plugin_name]):
                fn = self.plugins[plugin_name][function_name]
                hints = getattr(fn, "__annotations__", {})
                parameters = {}
                for parameter in inspect.signature(fn).parameters:
                    parameters[parameter] = getattr(
                        hints.get(parameter), "__name__", "string")
                entries.append({
                    "plugin": plugin_name,
                    "name": function_name,
                    "description": fn.__kernel_description__,
                    "parameters": parameters,
                })
        return entries

    def invoke(self, plugin_name, function_name, **kwargs):
        if plugin_name not in self.plugins:
            raise KeyError(f"no plugin {plugin_name!r}")
        functions = self.plugins[plugin_name]
        if function_name not in functions:
            raise KeyError(f"no function {plugin_name}.{function_name}")

        def call(args):
            return functions[function_name](**args)

        chain = call
        for outer in reversed(self.filters):
            chain = (lambda outer, inner: lambda args: outer(
                plugin_name, function_name, args, inner))(outer, chain)
        return chain(dict(kwargs))

    def render(self, template, **args):
        def replace(match):
            token = match.group(1).strip()
            if token.startswith("$"):
                name = token[1:]
                return str(args[name]) if name in args else match.group(0)
            if "." in token:
                plugin_name, _, function_name = token.partition(".")
                return str(self.invoke(plugin_name, function_name))
            return match.group(0)

        return re.sub(r"\{\{(.*?)\}\}", replace, template)

    def auto_invoke(self, goal, chooser, max_calls=5):
        calls = []
        for _ in range(max_calls):
            choice = chooser(goal, self.catalog(), list(calls))
            if choice is None:
                break
            plugin_name, function_name, args = choice
            result = self.invoke(plugin_name, function_name, **args)
            calls.append({"plugin": plugin_name, "name": function_name,
                          "args": args, "result": result})
        return calls
